  $('chat-source-limit').textContent='Последний рабочий чат представлен очищенными фрагментами, переданными пользователем. Свёрнутые сообщения не восстановлены. Отчёты о публикации и прохождении тестов не равны независимой проверке runtime.';
  const overview=$('overview'),intro=el('div',undefined,'archive-executive');
