  const current=el('p');current.append(el('strong','Текущий выбор: '),document.createTextNode(data.executive_summary.current_choice));intro.append(current);
  const pivot=el('p');pivot.append(el('strong','Поворотный момент: '),document.createTextNode(data.executive_summary.turning_point));intro.append(pivot);
  intro.append(el('p','Следующий контроль: '+data.executive_summary.remaining,'archive-scheme-note'));
  const sources=el('p',undefined,'archive-phase-meta');sources.append(link('Карта исследования в Miro','https://miro.com/app/board/uXjVEdObWRE=/?moveToWidget=3458764686735719516'),document.createTextNode(' · '),link('Срез кода: 10 октября, 17:12 UTC',data.current_code.source_url));intro.append(sources);
  intro.append(downloadLink('case-ui.ru.json',JSON.stringify(data,null,2),'application/json'));
  overview.insertBefore(intro,$('archive-counts'));
